import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import MobileMenu from './MobileMenu';
import '../styles/sidebar.css';

const Sidebar = () => {
  const [view, setView] = useState(false);
  // let element;
  const handleClick = () => {
    if(view == false) {
      setView(true)
    }
    if(view == true) {
      setView(false);
    }
  }

  return (
    <header className="side-bar-container">
      <title>Hatchers Podcast</title>
      <button className="mobile-menu-button" onClick={handleClick}>
        Menu
      </button>
      {/* {view == true ? <MobileMenu /> : */}
      {view == true ? <div className="hide-menu"></div> :
        <nav className="sidenav">
          <ul>
            <li><Link to="/home">Home</Link></li>
            <li><Link to="/guest-stars">Featured Guests</Link></li>
            <li><Link to="/features-in-fatherhood">Features In Fatherhood</Link></li>
            <li><Link to="/black-excellence">Black Excellence</Link></li>
            <li><Link to="/events">Events</Link></li>
            <li><Link to="/about">About</Link></li>
            {/* <li><Link to="/blog">Blog</Link></li> */}
            <li><Link to="/contact">Contact</Link></li>
          </ul>
        </nav>
      }
    </header>
  )
}

export default Sidebar;